        if arr[i-1] < arr[i] and arr[i] < arr[i+1]:
            l3+=arr[i]
    return max(l1,l2,l3)

def solve(lijst):
    sum = 0
    for index, item in enumerate(lijst):
        if index <= 1:
            sum = sum + item
        else:
            if lijst[index - 1] >= lijst[index - 2]:
                sum = sum + item

    return sum

def solve(els, i=0, seen=None):
    if i == len(els):
        return 0
    if seen is None:
        seen = set()
    result = 0
    for j in range(2, 4):
        if i+j not in seen:
            seen.add(i+j)
            result = max(result, els[i]+solve(els, i+j, seen))
            seen.remove(i+j)
    return result

def solve(remaining):
    if remaining == []:
        return 0

    elif len(remaining) == 1:
        return remaining[0]

    elif len(remaining) == 2:
        return remaining[0]

    elif remaining[0] + remaining[0] + remaining[0] + remaining[1] >= remaining[0] + remaining[1] + remaining[2]:
        return remaining[0] + remaining[0] + remaining[0] + remaining[1]
    else:
        return remaining[0] + remaining[0] + remaining[1]

def solve(elves):
    result = 0
    for i in range(0, len(elves)):
        if i < 2:
            result += elves[i]
        elif i == 2:
            result += max(elves[0], elves[1])
        elif i == 3:
            result += max(elves[0], elves[1], elves[2])
        else:
            result += max(elves[0], elves[1], elves[2], elves[i - 3], elves[i - 2], elves[i - 1])
    return result

def solve(As):
    if len(As) == 0:
        return 0
    if len(As) == 1:
        return As[0]
    count = 1
    i = 1
    while(i <= len(As)-1):
        if As[i] >= As[i-1]:
            count += 1
            i += 2
        else:
            count = 1
            i += 1
    if count >= 3:
        return sum(As)
    else:
        return sum(As[:2])

def solve(grades):
    grades = grades[::-1]
    if len(grades) < 2:
        return grades[0]
    elif len(grades) < 3:
        return max(grades[0], grades[1])
    elif len(grades) == 3:
        return max(grades[0] + grades[2], grades[1])

    grades.pop(0)
    grades.pop(0)
    grades.pop(1)
    grades.append(grades.pop(0))
    return max(grades[0] + solve(grades[1:]), solve(grades[2:]))
